// src/services/api.ts
const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

export interface ApiResponse<T> {
  success: boolean;
  data?: T;
  message?: string;
}

export const api = {
  // Authentication
  async login(email: string, password: string): Promise<ApiResponse<{ token: string; user: any }>> {
    const response = await fetch(`${API_BASE_URL}/auth/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password }),
    });
    return response.json();
  },

  // Dashboard Analytics
  async getDashboardStats(): Promise<ApiResponse<any>> {
    const token = localStorage.getItem('token');
    const response = await fetch(`${API_BASE_URL}/dashboard/stats`, {
      headers: { 'Authorization': `Bearer ${token}` },
    });
    return response.json();
  },

  // Parking Areas
  async getParkingAreas(): Promise<ApiResponse<any[]>> {
    const token = localStorage.getItem('token');
    const response = await fetch(`${API_BASE_URL}/parking/areas`, {
      headers: { 'Authorization': `Bearer ${token}` },
    });
    return response.json();
  },

  async addParkingArea(areaData: any): Promise<ApiResponse<any>> {
    const token = localStorage.getItem('token');
    const response = await fetch(`${API_BASE_URL}/parking/areas`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(areaData),
    });
    return response.json();
  },

  // Users Management
  async getUsers(): Promise<ApiResponse<any[]>> {
    const token = localStorage.getItem('token');
    const response = await fetch(`${API_BASE_URL}/users`, {
      headers: { 'Authorization': `Bearer ${token}` },
    });
    return response.json();
  },

  async addUser(userData: any): Promise<ApiResponse<any>> {
    const token = localStorage.getItem('token');
    const response = await fetch(`${API_BASE_URL}/users`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(userData),
    });
    return response.json();
  },

  async blockUser(userId: string): Promise<ApiResponse<any>> {
    const token = localStorage.getItem('token');
    const response = await fetch(`${API_BASE_URL}/users/${userId}/block`, {
      method: 'PUT',
      headers: { 'Authorization': `Bearer ${token}` },
    });
    return response.json();
  },

  // QR Scanning
  async validateQR(qrData: string): Promise<ApiResponse<any>> {
    const token = localStorage.getItem('token');
    const response = await fetch(`${API_BASE_URL}/qr/validate`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ qrData }),
    });
    return response.json();
  },
};
